def to_total_quantity(apps, schema_editor):
    """The old stored quantities become one total: available + on hold + sold. From now on, on hold
    and sold are derived from the orders instead."""
    Product = apps.get_model('product_app', 'Product')
    for product in Product.objects.all():
        product.total_quantity = product.quantity_available + product.quantity_on_hold + product.quantity_sold
        product.save(update_fields=['total_quantity'])


def from_total_quantity(apps, schema_editor):
    """Back to stored quantities: everything counts as available (orders no longer adjust them)."""
    Product = apps.get_model('product_app', 'Product')
    Product.objects.update(quantity_available=models.F('total_quantity'))


